    "motive": "飲み方の違う旅人",
    "intro": "卒業桜の学び舎の記録帳に、「ティーマッチャリバイバル」という頁が増える。灯花は飲み方の違う旅人が集まる喫茶卓で、まだ聞かれていない声に出会う。",
    "twist": "皆に同じ一杯を出すと苦手な人が黙り、一人ずつ選ぶには準備が足りない。船の便が来るまでに、住民と決める必要がある。 卒業桜の学び舎全体でも、同じ選び方が問われている。終わりを認めたくない住民が出航の鐘を止めてしまう。",
    "endingWarm": "温かな水や香りだけ楽しむ席を増やし、何も注文しない時間も受け入れる。卒業桜の学び舎の帳には、急がずに残した願いが一つ加わった。",
