    "twist": "大きく整った音だけを残すと、ためらいや沈黙に含まれる願いが聞こえなくなる。古い記録と今の希望が食い違い、灯花はどちらも確かめ直す。 白鐘の誓約島全体でも、同じ選び方が問われている。古い儀式は同じ形の幸福しか祝ってくれない。",
