    "twist": "一斉に収穫すると遅い実が育たず、待ち続けると先に熟した実が失われる。静寂の潮へ流れていた声が、ここでは別の姿で聞こえてくる。 一軒の出来事を記すうちに、一輪花の高原を揺らす事情が見えてくる。優れた花だけを咲かせる温室に、名のない種が閉じ込められる。",
