    "motive": "楽器でなく暮らしの音も集め",
    "intro": "残声の林間街の記録帳に、「夜に消えた聲」という頁が増える。灯花は楽器でなく暮らしの音も集める小さな演奏台で、まだ聞かれていない声に出会う。",
    "twist": "大きく整った音だけを残すと、ためらいや沈黙に含まれる願いが聞こえなくなる。船の便が来るまでに、住民と決める必要がある。 住民の相談を聞くと、島の大きな課題がここにも表れていた。大切だった過去を守るため、人々は変化を拒んでいる。",
