    "twist": "家族なら気持ちは同じはずという期待が、本人の選んだ暮らしを隠してしまう。古い記録と今の希望が食い違い、灯花はどちらも確かめ直す。 住民の相談を聞くと、島の大きな課題がここにも表れていた。大切だった過去を守るため、人々は変化を拒んでいる。",
