    "endingWarm": "記録と想像を分けて展示し、語れない部分には問いを残す。光太子の展望都の帳には、急がずに残した願いが一つ加わった。",
    "endingBrave": "複数の語り手に聞き、誰か一人の権威で未来の選択を決めない記録をつくる。奏は直した道具を住民へ渡す。次にどう使うかを決めるのは、ここで暮らす人たちだった。",
    "source": "title_inspired_original",
    "family": "history"
