    "twist": "強く照らすほど遠くへ届くが、近くの暮らしには眩しすぎる光になる。古い記録と今の希望が食い違い、灯花はどちらも確かめ直す。 一軒の出来事を記すうちに、光太子の展望都を揺らす事情が見えてくる。都の明るさを保つため、周辺の島へ暗闇が押し出される。",
    "endingWarm": "暗い席と明るい道を分け、住民が選べる灯りに変える。灯花はこの結末を完成の答えにせず、住民が続きを書ける記録へ返した。",
