    "twist": "声を止めれば静かになるが、鳥たちが何を知らせていたのか分からなくなる。静寂の潮へ流れていた声が、ここでは別の姿で聞こえてくる。 一軒の出来事を記すうちに、光太子の展望都を揺らす事情が見えてくる。都の明るさを保つため、周辺の島へ暗闇が押し出される。",
