    "twist": "高価な材料だけが讃えられ、時間や手間を贈った人が記録から外れる。奏は一度だけ試せる道具を用意する。やり直せる範囲を先に決めておく。 住民の相談を聞くと、島の大きな課題がここにも表れていた。高価な材料を出せる島だけが、中心に置かれようとする。",
