    "twist": "大きく整った音だけを残すと、ためらいや沈黙に含まれる願いが聞こえなくなる。船の便が来るまでに、住民と決める必要がある。 この出来事は、名付け前の交差島が抱える次の問題とつながっている。名前を先につけた国が島を所有するという古い掟がある。",
