    "intro": "根や枝が離れた場所を結ぶ緑の広場が、「赤陽樹」の物語の舞台になる。結び目の連絡港に着いた灯花と奏は、住民の願いを聞く。",
    "twist": "強く育つ木に光を集めると、小さな芽と木陰を必要とする草が失われる。古い記録と今の希望が食い違い、灯花はどちらも確かめ直す。 一軒の出来事を記すうちに、結び目の連絡港を揺らす事情が見えてくる。一つの結び目に便りが集中し、辺境の声が後回しになる。",
    "endingWarm": "明るい区画と木陰の区画を残し、異なる育ち方を見守る。次の港へ向かう荷物には、住民が選んだ小さな印が添えられた。",
    "endingBrave": "土と風を調べて苗を分け、森全体で光と水を渡す仕組みをつくる。小さな成功を全員の答えにせず、使う人が変えられる仕組みとして島へ残した。",
