    "endingWarm": "古い景色を絵に残し、今の住民が過ごす部屋も大切にする。次の港へ向かう荷物には、住民が選んだ小さな印が添えられた。",
    "endingBrave": "残す場所と変える場所を住民と決め、誰もが帰れる入口を整える。灯花は試した結果と残る課題を「帰途航路」の頁へ記す。新しい道は、また選び直せる。",
