    "twist": "声を止めれば静かになるが、鳥たちが何を知らせていたのか分からなくなる。一つの声だけで結論を出さず、まだ話していない住民にも席を残す。 住民の相談を聞くと、島の大きな課題がここにも表れていた。大きな功績のない住民が、復旧の話し合いから外される。",
    "endingWarm": "人が休む場所と鳥の暮らす木を分け、鳴く時間を一緒に見守る。「鳥と鈴と」の頁に、選ばなかった可能性も消さずに残した。",
    "endingBrave": "鳴き声と空模様を記録し、騒がしさの中にあった知らせを皆へ返す。その工夫を次の便で伝えると、石ころの河原の別の場所にも相談が生まれた。",
