    "intro": "頁ごとに異なる記憶が残る保存庫が、「若かった」の物語の舞台になる。空郵便の灯台群に着いた灯花と奏は、住民の願いを聞く。",
    "twist": "明るい記録だけを選ぶと痛みの理由が消え、全部開けば本人が守りたい秘密に触れる。奏は一度だけ試せる道具を用意する。やり直せる範囲を先に決めておく。 空郵便の灯台群全体でも、同じ選び方が問われている。危険な便を一人で抱えた奏が、灯花に相談せず旅立つ。",
    "endingWarm": "公開する頁を本人に選んでもらい、閉じた頁の場所も尊重する。次の港へ向かう荷物には、住民が選んだ小さな印が添えられた。",
    "endingBrave": "出所を確かめて複数の証言を残し、違いを無理に一つへまとめない。灯花は試した結果と残る課題を「若かった」の頁へ記す。新しい道は、また選び直せる。",
