    "twist": "一つの速さと習慣で暮らす決まりが、眠る時や動く道を狭めている。船の便が来るまでに、住民と決める必要がある。 この出来事は、月兎の観測庭が抱える次の問題とつながっている。現実へ戻すほど、一方の記憶が薄くなる装置が動いている。",
    "endingWarm": "眠る場所と遊ぶ場所を分け、互いの暮らしを邪魔しない距離を残す。灯花はこの結末を完成の答えにせず、住民が続きを書ける記録へ返した。",
    "endingBrave": "住民の動きを観察し、歩く、泳ぐ、跳ぶ道をつなぐ案内を整える。灯花は試した結果と残る課題を「月とウサギ」の頁へ記す。新しい道は、また選び直せる。",
