    "intro": "「玉砕卒業神」の頁を開くと、現幻の境界城の隣り合う机と旅立ちの印が置かれた学び舎へ道が続く。静寂の潮の中心に、記録官だけが入れる城が浮かぶ。",
    "twist": "旅立ちを祝う声が大きいほど、残ることを選んだ人が話しにくくなる。一つの声だけで結論を出さず、まだ話していない住民にも席を残す。 一軒の出来事を記すうちに、現幻の境界城を揺らす事情が見えてくる。城は苦しい記憶を消す代わりに、世界を救うと持ちかける。",
    "endingWarm": "進む人と残る人の記録を同じ棚へ置き、それぞれの願いを祝う。灯花はこの結末を完成の答えにせず、住民が続きを書ける記録へ返した。",
    "endingBrave": "新しい学び方と出発日を相談し、決め直しても戻れる窓口を開く。灯花は試した結果と残る課題を「玉砕卒業神」の頁へ記す。新しい道は、また選び直せる。",
