    "twist": "一つのよい未来を選ぶと、別の道を望む住民の可能性を閉じてしまう。道具は十分にない。何を先に守るかを、使う人自身へ尋ねる。 一軒の出来事を記すうちに、現幻の境界城を揺らす事情が見えてくる。城は苦しい記憶を消す代わりに、世界を救うと持ちかける。",
