    "endingWarm": "見るだけの道を残し、必要な分だけの水を時間を分けて借りる。月映りの公園の帳には、急がずに残した願いが一つ加わった。",
    "endingBrave": "水路を測り、岸を守りながら記録を写せる仕組みを奏とつくる。小さな成功を全員の答えにせず、使う人が変えられる仕組みとして島へ残した。",
