    "twist": "助ける側はいつも元気だと思われ、自分が休む希望を言えなくなっている。奏は一度だけ試せる道具を用意する。やり直せる範囲を先に決めておく。 一軒の出来事を記すうちに、余白のひだまり街を揺らす事情が見えてくる。復興の明るい記録に、悲しい声を置く余白がない。",
