    "intro": "余白のひだまり街で、灯花は「初恋恋歌」を題にした願いを一通ずつ預ける小さな相談台を訪ねる。嵐の後の街で、何も失っていないふりをする人々に出会う。",
    "twist": "気持ちの強さを示すほど、相手の返事を早く求めてしまいそうになる。道具は十分にない。何を先に守るかを、使う人自身へ尋ねる。 一軒の出来事を記すうちに、余白のひだまり街を揺らす事情が見えてくる。復興の明るい記録に、悲しい声を置く余白がない。",
    "endingWarm": "自分の願いと相手の自由を分けて記し、返事を待つ間の暮らしを整える。次の港へ向かう荷物には、住民が選んだ小さな印が添えられた。",
    "endingBrave": "伝えてよい時を確かめ、決めつけずに今の願いを短い言葉で届ける。その工夫を次の便で伝えると、余白のひだまり街の別の場所にも相談が生まれた。",
    "source": "title_inspired_original",
