    "endingWarm": "映る姿と本人の話を別々に残し、語りたくない頁は閉じておく。灯花はこの結末を完成の答えにせず、住民が続きを書ける記録へ返した。",
    "endingBrave": "窓を開く許可を確かめ、互いに聞きたいことを一つずつ交換する。奏は直した道具を住民へ渡す。次にどう使うかを決めるのは、ここで暮らす人たちだった。",
