    "twist": "目立つ演目ばかり残ると準備をした人の働きが見えず、全員を舞台に上げれば負担になる。道具は十分にない。何を先に守るかを、使う人自身へ尋ねる。 住民の相談を聞くと、島の大きな課題がここにも表れていた。復興の明るい記録に、悲しい声を置く余白がない。",
