    "motive": "隠れる場所を守る遊び",
    "intro": "名もなき桜の里を巡る旅。桜の里でかくれんぼを始めると、見つかりたくない住民も庭へ入ってくる。",
    "twist": "全員を見つければ成功という規則が、静かに過ごす権利まで奪いかけていた。 この出来事は、名もなき桜の里が抱える次の問題とつながっている。同じ色の桜しか育てない規則が、違う花を切り落とそうとする。",
    "endingWarm": "遊ぶ区域と休む区域を分け、参加の合図を確かめる。隠れることが、誰にでも説明を求められる理由ではなくなった。",
