    "twist": "好きな装いだけで本人の年齢や性格を決めつけると、対等に話す席が失われる。 この出来事は、恋心の発電港が抱える次の問題とつながっている。強い感情だけが力になり、穏やかな関係が無価値とされる。",
    "endingWarm": "着たい服と見せたい範囲を本人に選んでもらう。装いを楽しみながら、自分の言葉で暮らしを語れた。",
    "endingBrave": "役割の募集から外見の条件を外す。服の印象でなく本人の希望を確かめる会へ、衣装会を変えた。",
